// =====================
// Full Charge Logic (Victron)
// Output 1: DVCC Voltage
// Output 2: Write history (only on full charge)
// =====================

// ===== PARAMETERS =====
var DELTA_V              = 0.5;    // CVL drop detection (CVL mode only)
var FLOAT_VOLTAGE        = 53.9;   // Conservation charge voltage (V)
var FULL_CHARGE_INTERVAL = 2;      // Minimum interval: every N calendar weeks (1, 2, ...)
var AUTONOMOUS_MODE      = false;  // false = CVL detection | true = Autonomous mode
var RCV_VOLTAGE          = 55.2;   // Full charge voltage in autonomous mode (V)
var RCV_DETECT_DELTA     = 0.2;    // Voltage tolerance for RCV detection (V) — autonomous mode
var RCV_TIME_MIN         = 120;    // Hold time at RCV voltage (minutes) — autonomous mode
// =====================

function getKW(date) {
    var d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    var dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    var yearStart = new Date(Date.UTC(d.getUTCFullYear(),0,1));
    return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function weeksDiff(kwA, yearA, kwB, yearB) {
    // Total week difference across year boundaries
    if (yearA === yearB) return kwB - kwA;
    var lastKWofYearA = getKW(new Date(Date.UTC(yearA, 11, 28)));
    return (lastKWofYearA - kwA) + kwB;
}

function hhmm(d) {
    var h = ('0'+d.getHours()).slice(-2);
    var m = ('0'+d.getMinutes()).slice(-2);
    var s = ('0'+d.getSeconds()).slice(-2);
    return h+':'+m+':'+s;
}

var now = new Date();
var currentKW = getKW(now);
var currentYear = now.getFullYear();
var currentDateStr = now.toISOString().slice(0,10);
var nowTimeStr = hhmm(now);

// ----- Guard: History must be loaded -----
if (!flow.get('volladung_history_ready')) {
    node.status({ fill:'yellow', shape:'ring', text:'⏳ waiting for history... | '+nowTimeStr });
    return null;
}

// ----- Load history -----
var history = flow.get('volladung_history') || [];
var lastEntry    = history.length > 0 ? history[history.length-1] : null;
var lastFullKW   = lastEntry ? lastEntry.kw                    : currentKW;
var lastFullYear = lastEntry ? (lastEntry.year || currentYear) : currentYear;
var lastFullDate = lastEntry ? lastEntry.date                  : currentDateStr;

var modus = context.get('modus') || 'auto';
var fullChargeCount = context.get('fullChargeCount') || 0;

// ----- Mode Inject -----
if (typeof msg.payload === 'string') {
    if (['manual','bulk','auto'].indexOf(msg.payload) !== -1) {
        modus = msg.payload;
        context.set('modus', modus);
        context.set('lastModeChange', nowTimeStr);
        if (modus !== 'auto') {
            context.set('rcvActive', false);
            context.set('rcvHoldStart', null);
        }
        node.status({ fill:'blue', shape:'dot',
            text:'⚙ '+modus.toUpperCase()+' | W'+currentKW+' | last: W'+lastFullKW+' ('+lastFullDate+') | '+nowTimeStr });
    }
    return null;
}

// ----- Week difference -----
var kwDiff = weeksDiff(lastFullKW, lastFullYear, currentKW, currentYear);

// =====================================================================
// AUTONOMOUS MODE
// =====================================================================
if (AUTONOMOUS_MODE) {

    // ----- Battery voltage: hold timer logic -----
    if (msg.topic === 'bat_voltage') {
        var batV = msg.payload;
        if (typeof batV !== 'number') return null;

        var rcvActiveV = context.get('rcvActive') || false;
        if (!rcvActiveV || modus !== 'auto') return null;

        var rcvHoldStart = context.get('rcvHoldStart') || null;
        var threshold    = RCV_VOLTAGE - RCV_DETECT_DELTA;

        if (batV >= threshold) {
            if (!rcvHoldStart) {
                // Voltage first reached → start hold timer
                context.set('rcvHoldStart', now.getTime());
                node.status({ fill:'blue', shape:'dot',
                    text:'↑ RCV REACHED | '+batV.toFixed(2)+'V ≥ '+threshold.toFixed(2)+'V | Hold 0/'+RCV_TIME_MIN+'min | '+nowTimeStr });
            } else {
                var elapsedMin = (now.getTime() - rcvHoldStart) / 60000;
                if (elapsedMin >= RCV_TIME_MIN) {
                    // Full charge complete → Float
                    context.set('rcvActive', false);
                    context.set('rcvHoldStart', null);
                    fullChargeCount++;
                    context.set('fullChargeCount', fullChargeCount);
                    var entryA = { kw: currentKW, year: currentYear, date: currentDateStr };
                    history.push(entryA);
                    flow.set('volladung_history', history);
                    context.set('lastDVCC', FLOAT_VOLTAGE);
                    node.status({ fill:'green', shape:'dot',
                        text:'✓ FULL | DVCC='+FLOAT_VOLTAGE+'V | '+batV.toFixed(2)+'V | '+Math.round(elapsedMin)+'min | full='+fullChargeCount+' | '+nowTimeStr });
                    return [{payload: FLOAT_VOLTAGE}, {payload: JSON.stringify(history, null, 2)}];
                } else {
                    node.status({ fill:'blue', shape:'dot',
                        text:'↑ RCV HOLD | '+batV.toFixed(2)+'V | '+Math.round(elapsedMin)+'/'+RCV_TIME_MIN+'min | '+nowTimeStr });
                }
            }
        } else {
            if (rcvHoldStart) context.set('rcvHoldStart', null);
            node.status({ fill:'blue', shape:'dot',
                text:'↑ RCV CHARGING | '+batV.toFixed(2)+'V / '+RCV_VOLTAGE+'V | '+nowTimeStr });
        }
        return null;
    }

    // Ignore CVL messages (no BMS trigger needed)
    if (typeof msg.payload === 'number') return null;

    // ----- Heartbeat / Restart: DVCC output -----
    var rcvActive = context.get('rcvActive') || false;
    var dvccA;

    if (modus === 'manual') {
        dvccA = 0;
        context.set('rcvActive', false); context.set('rcvHoldStart', null);
        context.set('lastDVCC', dvccA);
        node.status({ fill:'yellow', shape:'dot', text:'⚡ MAN | DVCC=0 | '+nowTimeStr });
        return [{payload: dvccA}, null];
    }
    if (modus === 'bulk') {
        dvccA = FLOAT_VOLTAGE;
        context.set('rcvActive', false); context.set('rcvHoldStart', null);
        context.set('lastDVCC', dvccA);
        node.status({ fill:'grey', shape:'dot', text:'≈ BULK | DVCC='+dvccA+'V | '+nowTimeStr });
        return [{payload: dvccA}, null];
    }

    // AUTO
    if (rcvActive) {
        dvccA = RCV_VOLTAGE;
        context.set('lastDVCC', dvccA);
        var rcvHoldStartHB = context.get('rcvHoldStart') || null;
        var holdInfo = rcvHoldStartHB
            ? (Math.round((now.getTime()-rcvHoldStartHB)/60000)+'/'+RCV_TIME_MIN+'min hold')
            : 'waiting for voltage';
        node.status({ fill:'blue', shape:'dot',
            text:'↑ RCV | DVCC='+dvccA+'V | '+holdInfo+' | W'+currentKW+' | '+nowTimeStr });
        return [{payload: dvccA}, null];
    } else {
        if (kwDiff >= FULL_CHARGE_INTERVAL) {
            context.set('rcvActive', true);
            context.set('rcvHoldStart', null);
            dvccA = RCV_VOLTAGE;
            context.set('lastDVCC', dvccA);
            node.status({ fill:'blue', shape:'dot',
                text:'↑ RCV START | DVCC='+dvccA+'V | W'+currentKW+' last:W'+lastFullKW+' | '+nowTimeStr });
            return [{payload: dvccA}, null];
        } else {
            dvccA = FLOAT_VOLTAGE;
            context.set('lastDVCC', dvccA);
            node.status({ fill:'blue', shape:'dot',
                text:'● FLOAT | DVCC='+dvccA+'V | W'+currentKW+' last:W'+lastFullKW+' ('+lastFullDate+') | '+nowTimeStr });
            return [{payload: dvccA}, null];
        }
    }
}

// =====================================================================
// CVL MODE (default)
// =====================================================================

// ----- Heartbeat: Re-Evaluation -----
if (msg.topic === 'heartbeat') {
    var lastCVLhb = context.get('lastCVL');
    if (typeof lastCVLhb === 'number') {
        msg.payload = lastCVLhb;
    } else {
        var dvccHB;
        if (modus === 'manual') dvccHB = 0;
        else if (modus === 'bulk') dvccHB = FLOAT_VOLTAGE;
        else dvccHB = (kwDiff >= FULL_CHARGE_INTERVAL) ? 0 : FLOAT_VOLTAGE;
        context.set('lastDVCC', dvccHB);
        node.status({ fill:'cyan', shape:'dot',
            text:'⏱ HB(W-only) | DVCC:'+dvccHB+'V | W'+currentKW+' last:W'+lastFullKW+' ('+lastFullDate+') | '+nowTimeStr });
        return [{payload: dvccHB}, null];
    }
}

// ----- CVL Input -----
if (typeof msg.payload !== 'number') return null;
var currentCVL = msg.payload;
var msgCount = (context.get('msgCount') || 0) + 1;
context.set('msgCount', msgCount);
context.set('lastCVL', currentCVL);
context.set('lastUpdate', nowTimeStr);

var lastMaxCVL = context.get('lastMaxCVL');
if (lastMaxCVL === undefined) lastMaxCVL = currentCVL;

var dvccVoltage;
var fullChargeDetected = false;
var deltaVal = lastMaxCVL - currentCVL;

// ----- Logic -----
if (modus === 'manual') {
    dvccVoltage = 0;
} else if (modus === 'bulk') {
    dvccVoltage = FLOAT_VOLTAGE;
} else {
    if (deltaVal >= DELTA_V) {
        if (kwDiff >= FULL_CHARGE_INTERVAL) {
            fullChargeDetected = true;
            fullChargeCount++;
            context.set('fullChargeCount', fullChargeCount);
            var entry = { kw: currentKW, year: currentYear, date: currentDateStr };
            history.push(entry);
            flow.set('volladung_history', history);
            lastFullKW   = currentKW;
            lastFullYear = currentYear;
            lastFullDate = currentDateStr;
            kwDiff = 0;
        }
        lastMaxCVL = currentCVL;
    }
    if (currentCVL > lastMaxCVL) lastMaxCVL = currentCVL;
    dvccVoltage = (kwDiff >= FULL_CHARGE_INTERVAL) ? 0 : FLOAT_VOLTAGE;
}

// ----- Save context -----
context.set('lastMaxCVL', lastMaxCVL);
context.set('modus', modus);
context.set('lastDVCC', dvccVoltage);

// ----- Status display -----
var statusIcon, statusColor;
if (fullChargeDetected)      { statusIcon = '✓ FULL';  statusColor = 'green';  }
else if (modus === 'manual') { statusIcon = '⚡ MAN';   statusColor = 'yellow'; }
else if (modus === 'bulk')   { statusIcon = '≈ BULK';  statusColor = 'grey';   }
else if (dvccVoltage === 0)  { statusIcon = '↑ CHRG';  statusColor = 'blue';   }
else                         { statusIcon = '● FLOAT'; statusColor = 'blue';   }

node.status({
    fill: statusColor, shape: 'dot',
    text: statusIcon+
          ' | CVL:'+currentCVL.toFixed(2)+'V (max:'+lastMaxCVL.toFixed(2)+', Δ:'+deltaVal.toFixed(2)+')'+
          ' | DVCC:'+dvccVoltage+'V'+
          ' | W'+currentKW+' last:W'+lastFullKW+' ('+lastFullDate+')'+
          ' | n='+msgCount+' full='+fullChargeCount+
          ' | '+nowTimeStr
});

return [{ payload: dvccVoltage }, fullChargeDetected ? { payload: JSON.stringify(history, null, 2) } : null];

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);

var count = context.get('writeCount') || 0;
count++;
context.set('writeCount', count);

var v = msg.payload;
var label;
if (v === 0) label = 'DVCC=0 (BMS free)';
else label = 'DVCC='+v+'V';

node.status({
    fill: v === 0 ? 'blue' : 'green',
    shape: 'dot',
    text: label+' | writes:'+count+' | '+t
});

return msg;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2);

try {
    var history = JSON.parse(msg.payload);
    flow.set('volladung_history', history);
    flow.set('volladung_history_ready', true);

    var last = history.length > 0 ? history[history.length-1] : null;
    var lastText = last ? ('last: W'+last.kw+' ('+last.date+')') : 'no entries';

    node.status({
        fill:'green',
        shape:'dot',
        text: '✓ '+history.length+' entries | '+lastText+' | loaded '+t
    });
} catch (e) {
    flow.set('volladung_history', []);
    flow.set('volladung_history_ready', true);
    node.status({
        fill:'red',
        shape:'ring',
        text:'✗ History empty/invalid | '+t
    });
}
return null;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);
var dt = d.toISOString().slice(0,10);

var count = context.get('writes') || 0;
count++;
context.set('writes', count);

node.status({
    fill:'green',
    shape:'dot',
    text: '✓ written '+dt+' '+t+' | total:'+count
});
return null;
